//! Independent products of evaluated spontaneous fission.
//!
//! ENDF-102 (2023), §0.3.2.3 and §8.3, identifies NSUB=5 as spontaneous
//! fission yields and MT454 as direct products before subsequent decay:
//! <https://www.nndc.bnl.gov/endfdocs/ENDF-102-2023.pdf>.
//! The source's single LE=0 row is retained without normalization. MT459
//! cumulative yields would duplicate products generated by the decay network
//! and cannot substitute for this input.
//!
//! This type has no incident-neutron collapse or conversion to the induced
//! yield type. Half-life, branching, event energy and neutron emission remain
//! separate evaluated inputs; independent fragment yields establish none of
//! those quantities. Reported uncertainties are retained, not propagated as
//! numerical error or interpreted as independent covariance data.

use super::{
    EndfError, EndfFissionYieldReadLimits, EndfFissionYieldSelection, FissionYieldEvaluation,
    FissionYieldMetadata, FissionYieldValue, YieldSublibrary,
};
use crate::FissionError;
use crate::irradiation::NuclideId;

/// Identified immediate products per spontaneous-fission event.
/// The wrapped source is private so it cannot enter neutron-induced collapse.
#[derive(Clone, Debug, PartialEq)]
pub struct SpontaneousFissionYieldEvaluation {
    evaluation: FissionYieldEvaluation,
}

impl SpontaneousFissionYieldEvaluation {
    /// Read NSUB=5, MF8/MT454 using the original bounded ENDF record reader.
    /// One energy-independent yield set is required. Neither neutron-induced
    /// data, cumulative products, nor inferred missing products are admitted.
    pub fn parse(
        data_id: String,
        selection: EndfFissionYieldSelection,
        text: &str,
        limits: EndfFissionYieldReadLimits,
        mut checkpoint: impl FnMut() -> Result<(), FissionError>,
    ) -> Result<Self, EndfError> {
        let evaluation = FissionYieldEvaluation::parse_sublibrary(
            data_id,
            selection,
            text,
            limits,
            YieldSublibrary::Spontaneous,
            &mut checkpoint,
        )?;
        checkpoint()?;
        Ok(Self { evaluation })
    }

    #[must_use]
    pub fn data_id(&self) -> &str {
        self.evaluation.data_id()
    }

    #[must_use]
    pub fn metadata(&self) -> &FissionYieldMetadata {
        self.evaluation.metadata()
    }

    /// Original source order, including explicitly reported zero-yield products.
    #[must_use]
    pub fn products(&self) -> &[NuclideId] {
        self.evaluation.products()
    }

    /// The single source row's per-event multiplicities and reported uncertainty.
    #[must_use]
    pub fn values(&self) -> &[FissionYieldValue] {
        &self.evaluation.points()[0].values
    }

    /// The source's energy-field metadata [J]. It is not an irradiation energy,
    /// a decay energy, or a threshold; no incident-particle law is synthesized.
    #[must_use]
    pub fn source_energy_j(&self) -> f64 {
        self.evaluation.points()[0].energy_j
    }
}

